import json
from pathlib import Path
from collections import Counter

session_dir = Path("/Users/sashaabramovich/.claude/projects/-Users-sashaabramovich-live-spec")
files = sorted(list(session_dir.glob("*.jsonl")))

# Sample files from different dates
sample_files = [files[100], files[300], files[600], files[900], files[1200]]

offense_laws = Counter()
offense_quotes = []

for fpath in sample_files:
    try:
        with open(fpath, "r") as f:
            for line in f:
                try:
                    obj = json.loads(line)
                    if obj.get("type") == "assistant":
                        content = obj.get("message", {})
                        if isinstance(content, dict):
                            text = content.get("content", "")
                        else:
                            text = str(content)

                        if text.startswith("{") and "offences" in text:
                            try:
                                verdict = json.loads(text)
                                for off in verdict.get("offences", []):
                                    law_num = off.get("law")
                                    if law_num:
                                        offense_laws[law_num] += 1
                                        quote = off.get("quote", "")[:50]
                                        if quote:
                                            offense_quotes.append(quote)
                            except:
                                pass
                except:
                    pass
    except:
        pass

print("Offense frequency by law:")
for law, count in sorted(offense_laws.items(), key=lambda x: -x[1])[:10]:
    print(f"  Law {law}: {count} violations")

print("\nSample violations:")
for quote in offense_quotes[:10]:
    print(f"  '{quote}...'")

PYEOF
